from pathlib import Path
import hashlib
import json
import subprocess
import sys

FILES = {'config/application.example.json': '{\n  "clock_hz": 1000000000,\n  "data_transitions_per_s": 200000000,\n  "duty_high": 0.5,\n  "max_dffs": 8,\n  "condition_id": "UNCONFIRMED",\n  "input_slew_s": 2e-11,\n  "clock_slew_s": 2e-11,\n  "load_id": "UNCONFIRMED",\n  "interconnect_id": "UNCONFIRMED",\n  "min_dffs": 2\n}\n', 'config/parameters.synthetic.json': '{\n  "status": "synthetic_example_not_for_design",\n  "source": "Artificial numbers for software verification only; not extracted from the paper, PDK, or photographs.",\n  "tau_master_s": 2e-11,\n  "tau_slave_s": 3e-11,\n  "tw1_s": 1e-11,\n  "tw2_s": 2e-11,\n  "validated_scope": {}\n}\n', 'scripts/analyze.py': '"""CSV analysis helpers; fitted values are candidates, never automatically validated."""\nimport argparse\nimport csv\nimport json\nimport math\nfrom pathlib import Path\n\n\ndef linear_fit(x, y):\n    if len(x) < 5 or len(x) != len(y):\n        raise ValueError(\'At least five matching points required\')\n    if not all(math.isfinite(v) for v in x + y):\n        raise ValueError(\'Nonfinite input\')\n    mx, my = sum(x) / len(x), sum(y) / len(y)\n    xx = sum((v - mx) ** 2 for v in x)\n    if xx == 0:\n        raise ValueError(\'No independent-variable span\')\n    slope = sum((a - mx) * (b - my) for a, b in zip(x, y)) / xx\n    intercept = my - slope * mx\n    residuals = [b - (my + slope * (a - mx)) for a, b in zip(x, y)]\n    ss = sum(r * r for r in residuals)\n    total = sum((b - my) ** 2 for b in y)\n    return dict(slope=slope, intercept=intercept,\n                r_squared=1 - ss / total if total else 0,\n                rmse=math.sqrt(ss / len(x)), points=len(x),\n                slope_standard_error=math.sqrt(ss / (len(x) - 2) / xx))\n\n\ndef tau_fit(rows, start, stop):\n    if not all(math.isfinite(x) for x in (start, stop)) or start >= stop:\n        raise ValueError(\'Finite start < stop required\')\n    selected = [(float(r[\'time_s\']), float(r[\'delta_v\'])) for r in rows\n                if start <= float(r[\'time_s\']) <= stop]\n    if any(not math.isfinite(t) or not math.isfinite(v) or v == 0 for t, v in selected):\n        raise ValueError(\'delta_v must be finite and nonzero within fit interval\')\n    if any(selected[i][0] >= selected[i+1][0] for i in range(len(selected)-1)):\n        raise ValueError(\'time_s must be strictly increasing\')\n    if selected and any((v > 0) != (selected[0][1] > 0) for _, v in selected):\n        raise ValueError(\'delta_v changes sign: inspect common-mode/transient contamination\')\n    fit = linear_fit([t for t, _ in selected], [math.log(abs(v)) for _, v in selected])\n    if fit[\'slope\'] <= 0:\n        raise ValueError(\'Expected exponential growth, not decay\')\n    return dict(status=\'candidate\', tau_s=1 / fit[\'slope\'], fit=fit,\n                fit_start_s=start, fit_stop_s=stop,\n                notice=\'Good R2 alone is insufficient. Check window sensitivity, trace perturbation, latch phase, solver convergence and output saturation.\')\n\n\ndef aperture(rows, tm, ts):\n    if not all(math.isfinite(x) and x > 0 for x in (tm, ts)):\n        raise ValueError(\'Positive finite tau required\')\n    result = []\n    for row in rows:\n        raw_n = row[\'paper_n\']\n        if isinstance(raw_n, bool):\n            raise ValueError(\'paper_n must be a positive integer\')\n        numeric_n = float(raw_n)\n        if not math.isfinite(numeric_n) or not numeric_n.is_integer():\n            raise ValueError(\'paper_n must be a positive integer\')\n        n = int(numeric_n)\n        period, duty = float(row[\'period_s\']), float(row[\'duty_high\'])\n        lo, hi = float(row[\'delta_low_s\']), float(row[\'delta_high_s\'])\n        if n < 1 or not all(math.isfinite(x) for x in (period, duty, lo, hi)) or period <= 0 or not 0 < duty < 1 or hi <= lo:\n            raise ValueError(\'Invalid window row\')\n        width = hi - lo\n        if width >= period:\n            raise ValueError(\'Window must be smaller than a clock period\')\n        log_tw = math.log(width) + n * period * (duty / tm + (1 - duty) / ts)\n        if not math.isfinite(log_tw):\n            raise ValueError(\'Aperture exceeds numeric range\')\n        result.append(dict(paper_n=n, width_s=width, log_tw_s=log_tw,\n                           tw_s=math.exp(log_tw) if -700 < log_tw < 700 else None,\n                           status=\'candidate\', source=row))\n    return {\'status\': \'candidate\', \'results\': result,\n            \'notice\': \'Eq18 requires observations at N*T with consistent thresholds and load. Do not combine rows from different conditions. Inspect boundary uncertainty separately.\'}\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    sub = p.add_subparsers(dest=\'mode\', required=True)\n    t = sub.add_parser(\'tau\')\n    t.add_argument(\'--start\', type=float, required=True)\n    t.add_argument(\'--stop\', type=float, required=True)\n    w = sub.add_parser(\'aperture\')\n    w.add_argument(\'--tau-master\', type=float, required=True)\n    w.add_argument(\'--tau-slave\', type=float, required=True)\n    for s in (t, w):\n        s.add_argument(\'--csv\', required=True)\n        s.add_argument(\'--out\', required=True)\n    args = p.parse_args()\n    with Path(args.csv).open(encoding=\'utf-8-sig\', newline=\'\') as f:\n        rows = list(csv.DictReader(f))\n    if args.mode == \'tau\':\n        if args.start >= args.stop:\n            raise ValueError(\'start must be less than stop\')\n        result = tau_fit(rows, args.start, args.stop)\n    else:\n        result = aperture(rows, args.tau_master, args.tau_slave)\n    with Path(args.out).open(\'x\', encoding=\'utf-8\') as f:\n        json.dump(result, f, indent=2, ensure_ascii=False, allow_nan=False)\n    print(f\'Created {args.out} (candidate, not validated)\')\n\n\nif __name__ == \'__main__\':\n    main()\n', 'scripts/boundary.py': '"""Bracketed threshold search for a locally implemented simulator measurement callback.\n\nThis is a reusable algorithm, NOT an installed PrimeSim integration.\nevaluate(offset_s) must return a finite sampled voltage from a successful run.\n"""\nimport math\n\n\ndef bisect_threshold(evaluate, low_s, high_s, threshold_v, tolerance_s, max_iterations=80):\n    if not all(math.isfinite(x) for x in (low_s, high_s, threshold_v, tolerance_s)) or not low_s < high_s or tolerance_s <= 0:\n        raise ValueError(\'Invalid bracket/tolerance\')\n    history = []\n\n    def sample(x):\n        voltage = evaluate(x)\n        if not math.isfinite(voltage):\n            raise ValueError(\'Nonfinite simulator measurement\')\n        history.append({\'offset_s\': x, \'sample_v\': voltage})\n        return voltage - threshold_v\n\n    a, b = sample(low_s), sample(high_s)\n    if a == 0 or b == 0:\n        raise ValueError(\'Endpoint equals threshold; expand bracket to establish two-sided evidence\')\n    if (a > 0) == (b > 0):\n        raise ValueError(\'Threshold not bracketed\')\n    for _ in range(max_iterations):\n        if high_s - low_s <= tolerance_s:\n            return dict(low_s=low_s, high_s=high_s, uncertainty_s=high_s-low_s, history=history)\n        mid = low_s + (high_s - low_s) / 2\n        if mid in (low_s, high_s):\n            raise ValueError(\'Floating-point resolution exhausted\')\n        c = sample(mid)\n        if c == 0:\n            raise ValueError(\'Exact/quantized threshold sample; change bracket or inspect measurement precision\')\n        if (a > 0) == (c > 0):\n            low_s, a = mid, c\n        else:\n            high_s, b = mid, c\n    raise ValueError(\'Maximum iterations exceeded\')\n', 'scripts/check_environment.py': '"""Read-only environment inventory; does not probe licenses or launch simulators."""\nimport argparse\nimport json\nimport platform\nimport shutil\nimport sys\nfrom pathlib import Path\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument(\'--netlist\', required=True)\n    p.add_argument(\'--simulator\', help=\'Known executable path/name; no guessed version flags are run\')\n    p.add_argument(\'--out\', required=True)\n    args = p.parse_args()\n    netlist = Path(args.netlist)\n    executable = shutil.which(args.simulator) if args.simulator else None\n    if not executable and args.simulator and Path(args.simulator).is_file():\n        executable = str(Path(args.simulator).resolve())\n    result = dict(python_executable=sys.executable, python_version=sys.version,\n                  python_supported=sys.version_info >= (3, 9), os=platform.platform(),\n                  netlist_path=str(netlist.resolve()), netlist_exists=netlist.is_file(),\n                  simulator_requested=args.simulator, simulator_executable=executable,\n                  simulator_version=\'UNCONFIRMED\', license_status=\'UNCONFIRMED\',\n                  notice=\'Executable discovery does not prove simulator availability or license access.\')\n    with Path(args.out).open(\'x\', encoding=\'utf-8\') as f:\n        json.dump(result, f, ensure_ascii=False, indent=2)\n    print(json.dumps(result, ensure_ascii=False, indent=2))\n\n\nif __name__ == \'__main__\':\n    main()\n', 'scripts/inspect_netlist.py': '"""Read-only SPICE inventory. No topology or model functionality is inferred."""\nimport argparse\nimport collections\nimport hashlib\nimport json\nimport re\nfrom pathlib import Path\n\n\ndef logical_lines(text):\n    current, first = \'\', 0\n    for number, raw in enumerate(text.splitlines(), 1):\n        line = raw.strip()\n        if not line or line.startswith(\'*\'):\n            continue\n        if line.startswith(\'+\'):\n            if not current:\n                raise ValueError(f\'Orphan continuation at line {number}\')\n            current += \' \' + line[1:].strip()\n        else:\n            if current:\n                yield first, current\n            first, current = number, line\n    if current:\n        yield first, current\n\n\ndef inspect(path):\n    data = path.read_bytes()\n    text = data.decode(\'utf-8-sig\', errors=\'replace\')\n    counts = collections.Counter()\n    subckts, devices, references, models = [], [], [], []\n    scope = []\n    for number, line in logical_lines(text):\n        tokens = line.split()\n        head = tokens[0].lower()\n        if head == \'.subckt\':\n            scope.append(tokens[1])\n            pins = []\n            for token in tokens[2:]:\n                if \'=\' in token or token.lower() == \'params:\':\n                    break\n                pins.append(token)\n            subckts.append({\'name\': tokens[1], \'pins\': pins, \'line\': number})\n        elif head == \'.ends\':\n            if scope:\n                scope.pop()\n        elif head in (\'.include\', \'.inc\', \'.lib\'):\n            references.append({\'line\': number, \'text\': line})\n        elif head == \'.model\':\n            models.append({\'line\': number, \'text\': line})\n        elif not head.startswith(\'.\'):\n            kind = head[0].upper()\n            counts[kind] += 1\n            if kind in (\'M\', \'X\'):\n                entry = {\'line\': number, \'scope\': \'/\'.join(scope), \'kind\': kind,\n                         \'name\': tokens[0], \'statement\': line}\n                if kind == \'M\' and len(tokens) >= 6:\n                    entry.update(nodes=tokens[1:5], model=tokens[5])\n                else:\n                    entry[\'note\'] = \'X pin/model interpretation requires referenced SUBCKT definition; not guessed.\'\n                devices.append(entry)\n    return {\'file\': str(path.resolve()), \'sha256\': hashlib.sha256(data).hexdigest(),\n            \'decode_replacement_count\': text.count(\'\\ufffd\'), \'counts_by_prefix\': dict(counts),\n            \'subcircuits\': subckts, \'model_definitions\': models, \'include_and_lib_statements\': references,\n            \'device_statements\': devices,\n            \'has_direct_mos_statements\': counts[\'M\'] > 0,\n            \'has_subcircuit_calls\': counts[\'X\'] > 0,\n            \'candidate_net_labels\': sorted(set(re.findall(r\'^\\s*\\*\\|NET\\s+(\\S+)\', text, re.M))),\n            \'limits\': \'Does not resolve includes, validate model availability, infer master/slave nodes, or certify simulator compatibility. Full report may contain confidential connectivity.\'}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'netlist\')\n    parser.add_argument(\'--out\', required=True)\n    args = parser.parse_args()\n    report = inspect(Path(args.netlist))\n    out = Path(args.out)\n    out.mkdir(parents=True, exist_ok=False)\n    (out / \'netlist_inventory.json\').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding=\'utf-8\')\n    lines = [\'# Netlist inventory\', \'\', f\'SHA256: {report["sha256"]}\',\n             f\'Element counts: {report["counts_by_prefix"]}\',\n             f\'Direct MOS declarations: {report["has_direct_mos_statements"]}\',\n             f\'Subcircuit calls: {report["has_subcircuit_calls"]}\', \'\',\n             \'This inventory does not confirm master/slave topology or successful simulation.\', \'\', \'## Subcircuits\']\n    lines += [f\'- Line {s["line"]}: {s["name"]}; pins: {" ".join(s["pins"])}\' for s in report[\'subcircuits\']]\n    (out / \'summary.md\').write_text(\'\\n\'.join(lines) + \'\\n\', encoding=\'utf-8\')\n    print(f\'Created {out}; element counts={report["counts_by_prefix"]}\')\n\n\nif __name__ == \'__main__\':\n    main()\n', 'scripts/mtbf.py': '"""Beer et al. ASYNC 2013, equations 9, 17, 19. SI units throughout."""\nimport argparse\nimport csv\nimport json\nimport math\nfrom pathlib import Path\n\nYEAR = 365.25 * 86400\n\n\ndef positive(value, name):\n    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0:\n        raise ValueError(f"{name}: finite positive number required")\n    return value\n\n\ndef calculate(p, a):\n    for key in (\'tau_master_s\', \'tau_slave_s\', \'tw1_s\', \'tw2_s\'):\n        positive(p[key], key)\n    fc = positive(a[\'clock_hz\'], \'clock_hz\')\n    fd = positive(a[\'data_transitions_per_s\'], \'data_transitions_per_s\')\n    duty = positive(a[\'duty_high\'], \'duty_high\')\n    if duty >= 1:\n        raise ValueError(\'duty_high must be between 0 and 1\')\n    maximum = a.get(\'max_dffs\', 8)\n    minimum = a.get(\'min_dffs\', 2)\n    if isinstance(maximum, bool) or not isinstance(maximum, int) or maximum < 2:\n        raise ValueError(\'max_dffs must be an integer >= 2\')\n    if isinstance(minimum, bool) or not isinstance(minimum, int) or minimum < 2 or minimum > maximum:\n        raise ValueError(\'min_dffs must be an integer with 2 <= min_dffs <= max_dffs\')\n    inv_tau = duty / p[\'tau_master_s\'] + (1 - duty) / p[\'tau_slave_s\']\n    if not math.isfinite(inv_tau) or inv_tau <= 0:\n        raise ValueError(\'Effective time constant exceeds numeric range\')\n    scope = p.get(\'validated_scope\', {})\n    if not isinstance(scope, dict):\n        raise ValueError(\'validated_scope must be an object\')\n    reasons = []\n    if p.get(\'status\') != \'validated\':\n        reasons.append(\'parameters_not_validated\')\n    # An explicit, finite validated envelope is required for an in-scope result label.\n    for field, value in [(\'clock_hz\', fc), (\'duty_high\', duty)]:\n        bounds = scope.get(field)\n        if (not isinstance(bounds, list) or len(bounds) != 2\n                or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in bounds)\n                or bounds[0] > bounds[1] or not bounds[0] <= value <= bounds[1]):\n            reasons.append(f\'outside_or_missing_scope:{field}\')\n    for field in (\'condition_id\', \'input_slew_s\', \'clock_slew_s\', \'load_id\', \'interconnect_id\'):\n        av, pv = a.get(field), scope.get(field)\n        valid = True\n        if field.endswith(\'_slew_s\'):\n            try:\n                positive(av, field)\n                positive(pv, field)\n            except ValueError:\n                valid = False\n        else:\n            valid = isinstance(av, str) and bool(av.strip()) and av.upper() != \'UNCONFIRMED\'\n        if not valid or field not in scope or field not in a or pv != av:\n            reasons.append(f\'condition_mismatch_or_missing:{field}\')\n    validated_k = scope.get(\'max_dffs\', 0)\n    if isinstance(validated_k, bool) or not isinstance(validated_k, int):\n        validated_k = 0\n    rows = []\n    for k in range(minimum, maximum + 1):\n        n = k - 1\n        log_tw = math.log(p[\'tw1_s\']) + (n - 1) * (math.log(p[\'tw2_s\']) - math.log(p[\'tw1_s\']))\n        log_seconds = (n / fc * inv_tau - log_tw - math.log(fd) - math.log(fc)) / math.log(10)\n        log_years = log_seconds - math.log10(YEAR)\n        if not math.isfinite(log_years):\n            raise ValueError(\'Nonfinite result; input values exceed numeric range\')\n        flags = reasons + ([\'stage_count_not_validated\'] if k > validated_k else [])\n        log_probability = log_tw + math.log(fc) - n / fc * inv_tau\n        if log_probability >= 0:\n            flags.append(\'modeled_window_not_smaller_than_period\')\n        rows.append(dict(dff_count=k, paper_n=n, tau_effective_s=1 / inv_tau,\n                         log10_mtbf_seconds=log_seconds, log10_mtbf_years=log_years,\n                         mtbf_years_display=f\'10^({log_years:.6f})\',\n                         log10_window_fraction=log_probability / math.log(10),\n                         within_declared_scope=not flags,\n                         result_status=\'model_bound_within_declared_scope\' if not flags else \'unvalidated_model_calculation\',\n                         flags=\';\'.join(flags)))\n    return rows\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--parameters\', required=True)\n    parser.add_argument(\'--application\', required=True)\n    parser.add_argument(\'--out\', required=True, help=\'New output directory; existing directory refused\')\n    args = parser.parse_args()\n    p = json.loads(Path(args.parameters).read_text(encoding=\'utf-8-sig\'))\n    a = json.loads(Path(args.application).read_text(encoding=\'utf-8-sig\'))\n    rows = calculate(p, a)\n    out = Path(args.out)\n    out.mkdir(parents=True, exist_ok=False)\n    with (out / \'mtbf.csv\').open(\'w\', newline=\'\', encoding=\'utf-8-sig\') as f:\n        writer = csv.DictWriter(f, fieldnames=list(rows[0]))\n        writer.writeheader()\n        writer.writerows(rows)\n    report = {\'model\': \'Beer2013_eq9_eq17_eq19_identical_stages\',\n              \'parameters\': p, \'application\': a,\n              \'notice\': \'Flagged rows are unvalidated calculations, not established physical bounds. Legacy target_years is ignored. Validation status is supplied by the reviewer, not certified by this program.\',\n              \'rows\': rows}\n    (out / \'report.json\').write_text(json.dumps(report, ensure_ascii=False, indent=2, allow_nan=False), encoding=\'utf-8\')\n    lines = [\'# MTBF calculation\', \'\', f\'Parameter status: {p.get("status", "missing")}\',\n             \'No target input or minimum-count recommendation. Flagged rows are unvalidated model calculations.\',\n             \'\', \'Actual DFF count K; paper N = K - 1. Only reviewed in-scope values may be reported as model bounds.\', \'\',\n             \'| K | N | log10(MTBF / year) | Within declared scope | Flags |\',\n             \'|---|---|---|---|---|\']\n    lines += [f\'| {r["dff_count"]} | {r["paper_n"]} | {r["log10_mtbf_years"]:.6f} | {r["within_declared_scope"]} | {r["flags"]} |\' for r in rows]\n    (out / \'report.md\').write_text(\'\\n\'.join(lines) + \'\\n\', encoding=\'utf-8\')\n    print(f\'Created {out}; {len(rows)} per-count rows\')\n\n\nif __name__ == \'__main__\':\n    main()\n', 'scripts/run_case.py': '"""Generic simulator adapter. Uses explicit argv, shell=False, isolated new directory."""\nimport argparse\nimport hashlib\nimport json\nimport re\nimport subprocess\nimport time\nfrom pathlib import Path\n\n\ndef render(template, substitutions):\n    needed = set(re.findall(r\'@@([A-Z0-9_]+)@@\', template))\n    missing = needed - set(substitutions)\n    if missing:\n        raise ValueError(f\'Missing placeholders: {sorted(missing)}\')\n    for key in needed:\n        value = str(substitutions[key])\n        if \'\\n\' in value or \'\\r\' in value:\n            raise ValueError(\'Use template edits for multiline declarations\')\n        template = template.replace(\'@@\' + key + \'@@\', value)\n    if \'@@\' in template:\n        raise ValueError(\'Unresolved template marker\')\n    return template\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument(\'--config\', required=True)\n    p.add_argument(\'--out\', required=True)\n    p.add_argument(\'--execute\', action=\'store_true\', help=\'Default only renders; execution requires reviewed config\')\n    args = p.parse_args()\n    config_path = Path(args.config).resolve()\n    config = json.loads(config_path.read_text(encoding=\'utf-8-sig\'))\n    template_path = (config_path.parent / config[\'template\']).resolve()\n    deck = render(template_path.read_text(encoding=\'utf-8\'), config[\'substitutions\'])\n    argv = config[\'command_argv\']\n    if not isinstance(argv, list) or not argv or not all(isinstance(x, str) for x in argv):\n        raise ValueError(\'command_argv must be a nonempty string list\')\n    if args.execute and config.get(\'reviewed_for_local_environment\') is not True:\n        raise ValueError(\'Local review required: simulator syntax, pins, models, supplies, reset, measurements\')\n    if args.execute and any(marker in deck or any(marker in x for x in argv) for marker in (\'REQUIRED\', \'REPLACE_WITH_\', \'UNCONFIRMED\')):\n        raise ValueError(\'Unconfigured values remain; execution refused\')\n    out = Path(args.out).resolve()\n    out.mkdir(parents=True, exist_ok=False)\n    netlist = out / \'case.sp\'\n    netlist.write_text(deck, encoding=\'utf-8\')\n    argv = [x.replace(\'{netlist}\', str(netlist)).replace(\'{run_dir}\', str(out)) for x in argv]\n    record = dict(status=\'rendered_only\', argv=argv, config=config,\n                  deck_sha256=hashlib.sha256(deck.encode()).hexdigest(), start_unix=time.time())\n    code = 0\n    try:\n        if args.execute:\n            with (out / \'stdout.log\').open(\'w\', encoding=\'utf-8\') as stdout, (out / \'stderr.log\').open(\'w\', encoding=\'utf-8\') as stderr:\n                completed = subprocess.run(argv, cwd=out, stdout=stdout, stderr=stderr,\n                                           timeout=config.get(\'timeout_s\', 300), shell=False)\n            code = completed.returncode\n            record.update(returncode=code, status=\'process_finished_requires_output_review\' if code == 0 else \'process_failed\')\n    except (OSError, subprocess.TimeoutExpired) as exc:\n        record.update(status=\'execution_failed\', error=str(exc))\n        code = 1\n    finally:\n        record[\'finish_unix\'] = time.time()\n        (out / \'run_manifest.json\').write_text(json.dumps(record, indent=2, ensure_ascii=False), encoding=\'utf-8\')\n    print(f\'{record["status"]}: {out}\')\n    raise SystemExit(code)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'tests/test_audit.py': "import json\nimport math\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))\nfrom mtbf import calculate\nfrom analyze import aperture, tau_fit\n\n\nclass AuditTests(unittest.TestCase):\n    def setUp(self):\n        self.p = dict(tau_master_s=20e-12, tau_slave_s=30e-12, tw1_s=10e-12, tw2_s=20e-12)\n        self.a = dict(clock_hz=1e9, data_transitions_per_s=2e8, duty_high=.6)\n\n    def test_no_target_and_configurable_range(self):\n        rows = calculate(self.p, self.a)\n        self.assertEqual([r['dff_count'] for r in rows], list(range(2, 9)))\n        self.a.update(min_dffs=4, max_dffs=5, target_years=-100)\n        self.assertEqual([r['dff_count'] for r in calculate(self.p, self.a)], [4, 5])\n        self.assertFalse(any('target' in k or 'recommend' in k for k in rows[0]))\n\n    def test_invalid_range(self):\n        for value in ('8', True, 1, 2.5):\n            with self.assertRaises(ValueError):\n                calculate(self.p, dict(self.a, max_dffs=value))\n        with self.assertRaises(ValueError):\n            calculate(self.p, dict(self.a, min_dffs=5, max_dffs=3))\n\n    def test_eq18_then_eq17_cancels_to_window_rate(self):\n        # Independent probability interpretation: MTBF = T/(width*fD).\n        # A synthetic algebra check, NOT independent physical validation.\n        period, width = 1e-9, 2e-15\n        row = dict(paper_n=1, period_s=period, duty_high=.6, delta_low_s=0, delta_high_s=width)\n        tw = aperture([row], 20e-12, 30e-12)['results'][0]['tw_s']\n        p = dict(self.p, tw1_s=tw)\n        expected = math.log10(period / (width * self.a['data_transitions_per_s']))\n        self.assertAlmostEqual(calculate(p, self.a)[0]['log10_mtbf_seconds'], expected)\n\n    def test_no_assumed_stage_monotonicity(self):\n        p = dict(self.p, tw2_s=1e20)\n        rows = calculate(p, self.a)\n        self.assertLess(rows[1]['log10_mtbf_seconds'], rows[0]['log10_mtbf_seconds'])\n        self.assertIn('modeled_window_not_smaller_than_period', rows[-1]['flags'])\n\n    def test_slew_text_cannot_be_validated(self):\n        scope = dict(clock_hz=[1e9, 1e9], duty_high=[.6, .6], max_dffs=8)\n        for key in ('condition_id', 'load_id', 'interconnect_id', 'input_slew_s', 'clock_slew_s'):\n            self.a[key] = scope[key] = 'same'\n        self.p.update(status='validated', validated_scope=scope)\n        self.assertFalse(calculate(self.p, self.a)[0]['within_declared_scope'])\n\n    def test_fractional_stage_rejected(self):\n        for n in (1.9, True, 'nan'):\n            with self.assertRaises(ValueError):\n                aperture([dict(paper_n=n, period_s=1e-9, duty_high=.5, delta_low_s=0, delta_high_s=1e-15)], 2e-11, 2e-11)\n\n    def test_tiny_difference_does_not_underflow_sign_check(self):\n        rows = [dict(time_s=i*1e-12, delta_v=1e-200*math.exp(i/20)) for i in range(20)]\n        self.assertAlmostEqual(tau_fit(rows, 0, 19e-12)['tau_s']/2e-11, 1)\n\n    def test_nonfinite_aperture_rejected(self):\n        with self.assertRaises(ValueError):\n            aperture([dict(paper_n=1, period_s=1e308, duty_high=.5, delta_low_s=0, delta_high_s=1)], 1e-300, 1e-300)\n\n    def test_cli_outputs_seven_unvalidated_rows(self):\n        root = Path(__file__).resolve().parents[1]\n        with tempfile.TemporaryDirectory() as td:\n            out = Path(td)/'result'\n            proc = subprocess.run([sys.executable, str(root/'scripts/mtbf.py'), '--parameters', str(root/'config/parameters.synthetic.json'), '--application', str(root/'config/application.example.json'), '--out', str(out)], capture_output=True)\n            self.assertEqual(proc.returncode, 0, proc.stderr)\n            report = json.loads((out/'report.json').read_text(encoding='utf-8'))\n            self.assertEqual(len(report['rows']), 7)\n            self.assertNotIn('recommended_dffs', report)\n            self.assertTrue(all(not r['within_declared_scope'] for r in report['rows']))\n\n\nif __name__ == '__main__':\n    unittest.main()\n", 'tests/test_tools.py': 'import math\nimport sys\nimport tempfile\nimport subprocess\nimport json\nimport unittest\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / \'scripts\'))\nfrom mtbf import calculate, YEAR\nfrom analyze import tau_fit, aperture\nfrom inspect_netlist import inspect, logical_lines\nfrom run_case import render\nfrom boundary import bisect_threshold\n\n\nclass Tests(unittest.TestCase):\n    def setUp(self):\n        self.p = dict(tau_master_s=2e-11, tau_slave_s=2e-11, tw1_s=1e-11, tw2_s=2e-11, status=\'candidate\')\n        self.a = dict(clock_hz=1e9, data_transitions_per_s=2e8, duty_high=.5, max_dffs=8)\n\n    def test_single_resolution_period_and_recurrence(self):\n        rows = calculate(self.p, self.a)\n        expected = (50 - math.log(1e-11 * 1e9 * 2e8)) / math.log(10) - math.log10(YEAR)\n        self.assertAlmostEqual(rows[0][\'log10_mtbf_years\'], expected)\n        self.assertAlmostEqual(rows[1][\'log10_mtbf_years\'] - rows[0][\'log10_mtbf_years\'], (50-math.log(2))/math.log(10))\n        self.assertEqual([r[\'dff_count\'] for r in rows], list(range(2, 9)))\n\n    def test_data_rate(self):\n        r1 = calculate(self.p, self.a)\n        self.a[\'data_transitions_per_s\'] *= 10\n        r2 = calculate(self.p, self.a)\n        self.assertAlmostEqual(r1[0][\'log10_mtbf_years\'] - r2[0][\'log10_mtbf_years\'], 1)\n\n    def test_duty_and_large_exponent(self):\n        self.p[\'tau_slave_s\'] = 4e-11\n        self.a[\'duty_high\'] = .25\n        rows = calculate(self.p, self.a)\n        self.assertAlmostEqual(rows[0][\'tau_effective_s\'] / 1e-11, 3.2)\n        self.a[\'clock_hz\'] = 1e6\n        rows = calculate(self.p, self.a)\n        self.assertTrue(math.isfinite(rows[-1][\'log10_mtbf_years\']))\n\n    def test_scope_gate(self):\n        self.p[\'status\'] = \'validated\'\n        self.p[\'validated_scope\'] = dict(clock_hz=[1e9, 1e9], duty_high=[.5, .5], max_dffs=3)\n        for key in (\'condition_id\', \'input_slew_s\', \'clock_slew_s\', \'load_id\', \'interconnect_id\'):\n            self.a[key] = self.p[\'validated_scope\'][key] = 2e-11 if key.endswith(\'_slew_s\') else \'matching-test-value\'\n        rows = calculate(self.p, self.a)\n        self.assertTrue(rows[0][\'within_declared_scope\'])\n        self.assertFalse(rows[2][\'within_declared_scope\'])\n        self.a[\'load_id\'] = \'different\'\n        self.assertFalse(calculate(self.p, self.a)[0][\'within_declared_scope\'])\n\n    def test_invalid_input(self):\n        for value in (0, -1, math.nan, math.inf, True):\n            self.p[\'tau_master_s\'] = value\n            with self.assertRaises(ValueError):\n                calculate(self.p, self.a)\n\n    def test_tau_recovery(self):\n        rows = [dict(time_s=i*1e-12, delta_v=1e-5*math.exp(i/20)) for i in range(100)]\n        result = tau_fit(rows, 0, 99e-12)\n        self.assertAlmostEqual(result[\'tau_s\']/2e-11, 1)\n        self.assertAlmostEqual(result[\'fit\'][\'r_squared\'], 1)\n\n    def test_aperture_recovery(self):\n        width = 1e-11 * math.exp(-10)\n        rows = [dict(paper_n=\'1\', period_s=\'2e-10\', duty_high=\'.5\', delta_low_s=\'0\', delta_high_s=str(width))]\n        result = aperture(rows, 2e-11, 2e-11)\n        self.assertAlmostEqual(result[\'results\'][0][\'tw_s\']/1e-11, 1)\n\n    def test_inventory(self):\n        text = \'* Mfake a b c d model\\n.SUBCKT DFF CK D Q VDD VSS\\nM1 Q D VSS VSS nmos\\n+ L=1e-8\\nX1 Q CK model_sub\\nR1 Q n1 10\\nC1 n1 VSS 1e-15\\n.ENDS\\n\'\n        with tempfile.TemporaryDirectory() as directory:\n            path = Path(directory)/\'test.sp\'\n            path.write_text(text)\n            r = inspect(path)\n        self.assertEqual(r[\'counts_by_prefix\'], {\'M\':1,\'X\':1,\'R\':1,\'C\':1})\n        self.assertEqual(r[\'device_statements\'][0][\'model\'], \'nmos\')\n        self.assertIn(\'L=1e-8\', r[\'device_statements\'][0][\'statement\'])\n\n    def test_template(self):\n        self.assertEqual(render(\'R @@NODE@@ 0 1\', {\'NODE\':\'a\'}), \'R a 0 1\')\n        with self.assertRaises(ValueError):\n            render(\'@@MISSING@@\', {})\n\n    def test_threshold(self):\n        r = bisect_threshold(lambda x: x*x, 0, 2, 2, 1e-9)\n        self.assertLessEqual(r[\'low_s\'], math.sqrt(2))\n        self.assertGreaterEqual(r[\'high_s\'], math.sqrt(2))\n        with self.assertRaises(ValueError):\n            bisect_threshold(lambda x: x*x, 2, 3, 2, 1e-9)\n\n    def test_runner_process_failure_and_manifest(self):\n        # A Python stub checks process bookkeeping, not PrimeSim compatibility.\n        script = Path(__file__).resolve().parents[1] / \'scripts\' / \'run_case.py\'\n        with tempfile.TemporaryDirectory() as directory:\n            root = Path(directory)\n            (root/\'deck.in\').write_text(\'* test\\n.end\\n\')\n            config = dict(template=\'deck.in\', substitutions={}, reviewed_for_local_environment=True,\n                          command_argv=[sys.executable, \'-c\', \'print("stub failure"); raise SystemExit(7)\'])\n            (root/\'config.json\').write_text(json.dumps(config))\n            run = subprocess.run([sys.executable, str(script), \'--config\', str(root/\'config.json\'),\n                                  \'--out\', str(root/\'run\'), \'--execute\'], capture_output=True)\n            self.assertEqual(run.returncode, 7)\n            record = json.loads((root/\'run\'/\'run_manifest.json\').read_text())\n            self.assertEqual(record[\'status\'], \'process_failed\')\n            self.assertIn(\'stub failure\', (root/\'run\'/\'stdout.log\').read_text())\n\n    def test_runner_blocks_unreviewed_execution(self):\n        script = Path(__file__).resolve().parents[1] / \'scripts\' / \'run_case.py\'\n        with tempfile.TemporaryDirectory() as directory:\n            root = Path(directory)\n            (root/\'deck.in\').write_text(\'* test\\n.end\\n\')\n            config = dict(template=\'deck.in\', substitutions={}, reviewed_for_local_environment=False,\n                          command_argv=[sys.executable, \'-c\', \'raise SystemExit(0)\'])\n            (root/\'config.json\').write_text(json.dumps(config))\n            run = subprocess.run([sys.executable, str(script), \'--config\', str(root/\'config.json\'),\n                                  \'--out\', str(root/\'run\'), \'--execute\'], capture_output=True)\n            self.assertNotEqual(run.returncode, 0)\n            self.assertFalse((root/\'run\').exists())\n\n\nif __name__ == \'__main__\':\n    unittest.main()\n', 'UPDATE_20261001.md': '# 2026-10-01 업데이트: 진행 중 작업을 보존하는 설치\n\n처음부터 다시 실험하지 않습니다. 기존 코드/덱/결과는 현재 위치에 두고, 수정된 계산 도구만 옆의 새 폴더에 설치합니다. 기존 실행에 자동 적용되거나 기존 Python import 경로를 바꾸지 않습니다.\n\n## 지금 할 일\n\n1. GitHub의 `COPY_THIS_update_20261001.py`를 열고 Copy raw file로 전체 내용을 복사합니다.\n2. AA PC의 기존 작업 폴더를 담은 상위 폴더(예: CCODE)에 같은 이름으로 저장합니다. 폴더 이름 철자를 바꿀 필요는 없습니다. 실행 중인 터미널에 명령을 입력하지 말고 별도 터미널을 사용합니다.\n3. 저장한 파일이 있는 폴더에서 다음 한 줄을 실행합니다. 기존에 확인한 Python 3 실행 경로를 사용해도 됩니다.\n\n```text\npython3 COPY_THIS_update_20261001.py\n```\n\n설치 파일 옆에 `mtbf_tools_20261001`을 자동 생성하고 21개 소프트웨어 테스트를 실행합니다. 마지막에 `UPDATE_READY`가 표시되면 설치가 끝났습니다. `EXISTS_NO_CHANGES`이면 이미 같은 이름의 폴더가 있으므로 중단한 것입니다. 기존 폴더를 삭제하거나 덮어쓰지 말고 메시지를 확인합니다.\n\n네트워크, pip 설치, PrimeSim 실행, 기존 작업 폴더 탐색/수정은 하지 않습니다. 테스트는 합성 데이터와 임시 파일을 사용하며 실제 MTBF 측정이 아닙니다. 표준 라이브러리와 기존 Python만 사용합니다. 기존 실험은 그대로 이어갑니다.\n\n```text\n현재 상위 폴더/\n  기존 작업 폴더/          <- 기존 덱, 결과, 실행을 그대로 유지\n  COPY_THIS_update_20261001.py\n  mtbf_tools_20261001/     <- 자동 생성되는 수정 계산 도구\n```\n\n## 무엇이 바뀌었나\n\n- 목표 MTBF 입력/최소 DFF 추천을 제거하고 기본 실제 DFF K=2~8개를 계산합니다. min_dffs/max_dffs로 범위를 변경합니다.\n- 숫자 slew, 정수 단계, 수치 범위 검증을 보완합니다.\n- 검토 범위 밖 결과를 미검증 계산으로 표시합니다.\n- 실제 파라미터를 얻은 다음 새 도구로 계산합니다. 예제 값은 합성값이므로 설계에 사용하지 않습니다.\n- Python 함수 calculate(p,a)는 이제 rows만 반환합니다. 기존 (rows,recommendation) 호출을 자동으로 바꾸지 않습니다.\n\n## 기존 작업과 이어 쓰기\n\n완료된 넷리스트 조사, 정상 동작, 관측점 식별을 다시 하지 않습니다. 기존 파형과 로그도 이동할 필요가 없습니다. 추출값을 검토한 뒤 새 계산기에 입력하면 됩니다. AA PC에서 별도로 작성한 추출 스크립트는 이 업데이트에 포함되지 않습니다.\n\n진행 중 코드에 대한 자동 덮어쓰기 기능은 제공하지 않습니다. 실행 중 파일을 바꾸면 후속 실행이 서로 다른 버전의 코드를 사용할 수 있기 때문입니다. 기존 작업이 끝난 뒤 필요하면 파일별 차이와 백업을 확인하여 병합합니다. 지금은 새 도구 경로를 명시해서 쓰면 됩니다.\n\n## Luna 등 다른 모델로 이어갈 때\n\n설치 자체는 AI 없이 한 명령으로 끝납니다. 모델을 바꿔 이후 작업을 이어갈 때는 생성된 `AA_PC_AGENT_BRIEF.md`를 읽히고 최근 `RETURN_TO_REVIEWER.md`의 경로를 지정합니다. 이전 대화 전체/PDK 전체를 다시 읽히지 않습니다. 모델별 실제 크레딧 차감은 AA PC 제공자의 표시를 확인합니다.\n\n## 범위\n\n이 업데이트는 계산/분석 보조 도구 수정입니다. PrimeSim 특성화 어댑터, 네 개의 실측 파라미터, 물리적 MTBF 검증이 자동 완성되는 것은 아닙니다. 원문 이론은 Beer et al., ASYNC 2013의 식 (9), (17), (18), (19)를 따릅니다. 기존 루트 문서와 bootstrap은 이전 버전 기록이며 이 업데이트의 목표/실행 안내를 우선합니다.\n', 'AA_PC_AGENT_BRIEF.md': '# AA PC 작업 인계: 작은 실행 단위\n\n목표: 동일 DFF의 실제 개수 K=2~8(변경 가능)에 대한 조건별 MTBF 모델 하한 표. 목표 MTBF나 최소 개수 추천은 필요 없다. 네 파라미터 tau_M/tau_S/TW1/TW2가 검증되기 전에는 설계용 MTBF를 보고하지 않는다.\n\n업데이트 설치는 끝난 것으로 가정하지 말고 UPDATE_READY/설치 테스트 결과를 확인한다. 기존 실험 폴더는 실행 중일 수 있으므로 수정/이동/삭제하지 않는다. 이 새 도구는 기존 연구를 처음부터 다시 시작하라는 뜻이 아니다.\n\n## 최초 응답에서 할 일\n\n사용자가 지정한 최신 RETURN_TO_REVIEWER.md만 먼저 읽는다. 위치가 없으면 경로를 물어본다. 전체 PDK 재탐색이나 시뮬레이션 재실행은 하지 않는다. 보고서에서 확인되는 완료 항목, 마지막 실행 결과, 다음 막힌 점을 10줄 이내로 정리한다. 보고서에 없는 사실을 추측하지 않는다.\n\n## 실행을 지시받으면\n\n- 검증된 덱/실행 스크립트와 지정된 CSV를 우선 재사용한다.\n- 새 실험은 별도 결과 폴더에 보관한다. 기존 파일에 덮어쓰지 않는다.\n- 지시된 case만 실행한다. 자동으로 범위를 늘리거나 모델/문턱/주기를 바꾸지 않는다.\n- case 반복은 스크립트로 처리한다. 매 case 덱 재작성/장문 파형 설명은 하지 않는다.\n- 오류가 반복되면 1회 원인 확인 후 실행 수·로그 근거와 함께 보고한다. PDK를 수정하거나 임의 파라미터를 넣지 않는다.\n- 종료 코드만으로 성공 판정하지 않는다. 필요한 노드, 파형, 모델 경고를 확인한다.\n- 보고는 실행 수/성공·실패/출력 경로/막힌 원인/다음 판단에 필요한 값만 간결하게 한다.\n- 0.5 VDD crossing, 캡처 경계 폭, TW는 같은 개념이 아니다. 물리 해석이 필요한 부분은 검토 대상으로 남긴다.\n\n## 새 계산기 사용\n\n기본 min_dffs=2, max_dffs=8이며 수정 가능하다. target_years는 필요 없다. 기존 calculate API의 tuple 반환은 rows 목록으로 변경됐다. 기존 추출 코드가 이 함수를 호출하면 작업 종료 후 별도로 호출부를 검토한다. AI가 임의로 진행 중 코드를 일괄 수정하지 않는다.\n'}
HASHES = {'config/application.example.json': '9774a5e18faf10f735f309766f23dc758a36c24650ac9ebe78210ec0ff9a0add', 'config/parameters.synthetic.json': 'f93ad0ed119b655a813fa8a881457cf0943cd96d9a0112a5ed01b01c50ec67af', 'scripts/analyze.py': 'f6f2af091fef2416aa221c425ac59e184667520ac983593601e958bf23446caf', 'scripts/boundary.py': 'fa733e5249b93e48275f3c9c3d90ee28a8aecc69c78d979d1519315bd95bd45e', 'scripts/check_environment.py': 'a302759040e25aa7e776b70a9186e95cf749388b2e3aca0ea73158890d9213fb', 'scripts/inspect_netlist.py': '8603c4568d7b3002474d55df0bfaf374d301a87809d6b2073bf008c5fff04bea', 'scripts/mtbf.py': 'e712eab10df1adf873486e0b049c9a64fc2496b3a87cdba803b92ae396f23d17', 'scripts/run_case.py': '3be98e0e254f7e77f4cc384aa2a4992c7a9d12671ef4f3f5090845f01c88a8cb', 'tests/test_audit.py': 'cda94e65da29053ad9262d604c24039f230fa2990a97bb4e58993e6efb874c68', 'tests/test_tools.py': '764f363f4e20e9f332d003ad5aa0ff930a2cddb74c287b93849b02d9c2b754f6', 'UPDATE_20261001.md': 'fc2651135d45b520e2793719d6882316bf39ff4feeb30f1b44c58dc47dc8612c', 'AA_PC_AGENT_BRIEF.md': '5c1dfc1283a1b29c1aa9719eebcf47276b347825ee1c11d6c7b3ce8b48185249'}


def main():
    dest = Path(__file__).resolve().parent / 'mtbf_tools_20261001'
    if dest.exists() or dest.is_symlink():
        print('EXISTS_NO_CHANGES:', dest)
        print('Existing directory was not modified. Review its test_results.txt.')
        return 2
    for name, content in FILES.items():
        if hashlib.sha256(content.encode('utf-8')).hexdigest() != HASHES[name]:
            raise ValueError('Bundle copy/hash mismatch: ' + name)
    dest.mkdir(exist_ok=False)
    for name, content in FILES.items():
        p = dest / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(content.encode('utf-8'))
    (dest/'BUNDLE_MANIFEST.json').write_text(json.dumps(HASHES, indent=2), encoding='utf-8')
    try:
        proc = subprocess.run([sys.executable, '-m', 'unittest', 'discover', '-s', 'tests', '-v'],
                              cwd=dest, capture_output=True, timeout=60)
    except (OSError, subprocess.TimeoutExpired) as exc:
        (dest/'test_results.txt').write_text(str(exc), encoding='utf-8')
        print('UPDATE_TEST_FAILED:', dest)
        return 1
    output = proc.stdout + proc.stderr
    (dest/'test_results.txt').write_bytes(output)
    print(output.decode('utf-8', errors='replace'))
    if proc.returncode != 0:
        print('UPDATE_TEST_FAILED:', dest)
        return 1
    print('UPDATE_READY:', dest)
    print('Existing simulations and files were not modified. No need to restart research.')
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
